import java.nio.file.*;import java.util.*;import javax.tools.*;import javax.lang.model.element.*;import javax.lang.model.type.*;import com.sun.source.tree.*;import com.sun.source.util.*;
/** Conservative literal-only candidate attribution; runtime oracle must approve each candidate. */
public class BoxFactoryScanner {
 static boolean constant(ExpressionTree n){switch(n.getKind()){case INT_LITERAL:case LONG_LITERAL:case FLOAT_LITERAL:case DOUBLE_LITERAL:return true;case PARENTHESIZED:return constant(((ParenthesizedTree)n).getExpression());case UNARY_MINUS:case UNARY_PLUS:return constant(((UnaryTree)n).getExpression());case PLUS:case MINUS:case MULTIPLY:case DIVIDE:return constant(((BinaryTree)n).getLeftOperand())&&constant(((BinaryTree)n).getRightOperand());default:return false;}}
 public static void main(String[] a)throws Exception{
 JavaCompiler c=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject>d=new DiagnosticCollector<>();StandardJavaFileManager f=c.getStandardFileManager(d,null,null);JavacTask t=(JavacTask)c.getTask(null,f,d,Arrays.asList("-proc:none","-source","8","-classpath",new String(Files.readAllBytes(Paths.get(a[1]))).trim(),"-Xmaxerrs","100000"),null,f.getJavaFileObjectsFromStrings(Files.readAllLines(Paths.get(a[0]))));Trees tr=Trees.instance(t);List<CompilationUnitTree>us=new ArrayList<>();for(CompilationUnitTree u:t.parse())us.add(u);t.analyze();
 for(CompilationUnitTree u:us){Set<String> shadows=new HashSet<>();new TreeScanner<Void,Void>(){public Void visitVariable(VariableTree n,Void v){shadows.add(n.getName().toString());return super.visitVariable(n,v);}public Void visitClass(ClassTree n,Void v){shadows.add(n.getSimpleName().toString());return super.visitClass(n,v);}public Void visitTypeParameter(TypeParameterTree n,Void v){shadows.add(n.getName().toString());return super.visitTypeParameter(n,v);}}.scan(u,null);
 new TreePathScanner<Void,Void>(){public Void visitMethodInvocation(MethodInvocationTree n,Void v){if(n.getMethodSelect() instanceof MemberSelectTree){MemberSelectTree s=(MemberSelectTree)n.getMethodSelect();TreePath sp=new TreePath(getCurrentPath(),s);Element e=tr.getElement(new TreePath(sp,s.getExpression()));String r=s.getExpression().toString();if(s.getIdentifier().contentEquals("getBoundingBox")&&e instanceof TypeElement&&((TypeElement)e).getQualifiedName().contentEquals("net.minecraft.util.math.AxisAlignedBB")&&((r.equals("AxisAlignedBB")&&!shadows.contains(r))||(r.equals("net.minecraft.util.math.AxisAlignedBB")&&!shadows.contains("net")))&&n.getArguments().size()==6){boolean valid=true;for(ExpressionTree arg:n.getArguments()){TypeMirror ty=tr.getTypeMirror(new TreePath(getCurrentPath(),arg));valid&=constant(arg)&&ty!=null&&Arrays.asList(TypeKind.BYTE,TypeKind.SHORT,TypeKind.INT,TypeKind.LONG,TypeKind.FLOAT,TypeKind.DOUBLE,TypeKind.CHAR).contains(ty.getKind());}if(valid)System.out.println(Paths.get(u.getSourceFile().toUri())+"\t"+tr.getSourcePositions().getStartPosition(u,n)+"\t"+tr.getSourcePositions().getEndPosition(u,s)+"\t"+tr.getSourcePositions().getEndPosition(u,n));}}return super.visitMethodInvocation(n,v);}}.scan(u,null);}
 System.err.println("Attribution only, unfinished-port errors: "+d.getDiagnostics().stream().filter(x->x.getKind()==Diagnostic.Kind.ERROR).count());f.close();}
}
